		movers.push(new Mover03(x, y));
		movers.push(new Mover04(x, y));
		movers.push(new Mover05(x, y));
	}
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

